describe('DELETE /v1/projects/:projectId', () => {
  it('deletes a project and returns 204 with no body', async () => {
    const project = await createProject();
    const res = await request(app).delete(`/v1/projects/${project.id}`);
    expect(res.status).toBe(204);
    expect(res.text).toBe('');

    expectProblem(await request(app).get(`/v1/projects/${project.id}`), 404);
    expectProblem(await request(app).delete(`/v1/projects/${project.id}`), 404);
  });

  it('answers a malformed id with a 422 problem', async () => {
    expectProblem(await request(app).delete('/v1/projects/not-a-uuid'), 422);
  });
});

describe('GET /v1/projects with status filters', () => {
  it('filters archived and active projects before paginating', async () => {
    const archivedOne = await createProject({ status: 'archived' });
    const active = await createProject({ status: 'active' });
    const archivedTwo = await createProject({ status: 'archived' });

    const archivedIds = await listAll({ limit: '1', status: 'archived' });
    expect(archivedIds).toEqual([archivedOne.id, archivedTwo.id]);

    const activeIds = await listAll({ limit: '1', status: 'active' });
    expect(activeIds).toEqual([active.id]);
  });

  it('rejects an unknown status with a 422 problem', async () => {
    expectProblem(await request(app).get('/v1/projects').query({ status: 'deleted' }), 422);
  });
});

