 1| import { randomUUID } from 'node:crypto';
 2| import { paginate } from '../../lib/pagination.ts';
 3| import type { CreateProject, ListProjectsQuery, Project, ProjectPage, UpdateProject } from './schema.ts';
 4| 
 5| /** In-memory project store, ordered by creation time (ties broken by id). */
 6| const projects = new Map<string, Project>();
 7| 
 8| const sortKey = (project: Project): string => `${project.createdAt}|${project.id}`;
 9| 
10| export function listProjects(query: ListProjectsQuery): ProjectPage {
11|   const filtered = query.status === undefined ? [...projects.values()] : [...projects.values()].filter((project) => project.status === query.status);
12|   return paginate(filtered, query, sortKey);
13| }
14| 
15| export function getProject(id: string): Project | undefined {
16|   return projects.get(id);
17| }
18| 
19| export function createProject(input: CreateProject): Project {
20|   const now = new Date().toISOString();
21|   const project: Project = { id: randomUUID(), ...input, createdAt: now, updatedAt: now };
22|   projects.set(project.id, project);
23|   return project;
24| }
25| 
26| export function updateProject(id: string, patch: UpdateProject): Project | undefined {
27|   const current = projects.get(id);
28|   if (current === undefined) return undefined;
29|   const updated: Project = { ...current, ...patch, updatedAt: new Date().toISOString() };
30|   projects.set(id, updated);
31|   return updated;
32| }
33| 
34| export function deleteProject(id: string): boolean {
35|   return projects.delete(id);
36| }

